#!/usr/bin/env python3
"""Build the shipment summary described in /app/docs/summary-format.md."""
import csv
import gzip
import io
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, InvalidOperation

DEPOT_ORDER = ["central", "south", "east", "river", "north", "west", "harbor", "lakeside"]
UNIT_KG = {"kg": Decimal(1), "g": Decimal("0.001"), "lb": Decimal("0.45359237"),
           "oz": Decimal("0.028349523125")}
MONTHS = {m: i + 1 for i, m in enumerate(
    ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"])}

COLUMNS = {
    "east": ["id", "type", "shipped", "gross", "net", "status", "note"],
    "harbor": ["rec", "ref", "date", "weight", "state"],
    "lakeside": ["id", "kind", "booked", "shipped", "gross_kg", "net_kg", "status"],
    "river": ["t", "ref", "shipped", "weight", "status"],
    "west": ["id", "typ", "shipped", "weight", "status", "note"],
}
DELIM = {"east": ",", "lakeside": ",", "harbor": "|", "river": "\t", "west": ";"}
BASE_DATE = {"east": "YMD", "harbor": "iso", "lakeside": "iso", "river": "MM/DD/YYYY",
             "west": "DD.MM.YYYY"}
# (decimal mark, thousands mark)
NUMFMT = {"east": (".", ","), "west": (",", ".")}
TYPE_MAP = {"n": "new", "new": "new", "": "new", "c": "correction", "cor": "correction",
            "corr": "correction", "correction": "correction", "amend": "correction",
            "v": "void", "void": "void"}


# ---------------------------------------------------------------- bytes/text
def read_bytes(path):
    with open(path, "rb") as fh:
        data = fh.read()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    return data


def decode(data):
    if data[:3] == b"\xef\xbb\xbf":
        return data[3:].decode("utf-8", "replace")
    if data[:2] == b"\xff\xfe":
        return data[2:].decode("utf-16-le", "replace")
    if data[:2] == b"\xfe\xff":
        return data[2:].decode("utf-16-be", "replace")
    head = data[:2048].decode("latin-1")
    m = re.search(r"^#\s*charset\s*:\s*([\w.\-]+)", head, re.M | re.I)
    if m:
        try:
            return data.decode(m.group(1))
        except (LookupError, UnicodeDecodeError):
            return data.decode("latin-1")
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        return data.decode("latin-1")


# ---------------------------------------------------------------- values
def shipment_number(raw):
    m = re.search(r"\d+", raw or "")
    return int(m.group(0)) if m else None


def norm_status(raw):
    return re.sub(r"[\s\-]+", "_", (raw or "").strip().lower())


def counted(status):
    return status in ("delivered", "delivered_late")


def norm_unit(raw):
    if not raw:
        return None
    m = re.match(r"\s*([A-Za-z]+)", raw)
    if not m:
        return None
    u = m.group(1).lower()
    u = {"kgs": "kg", "lbs": "lb", "gram": "g", "grams": "g", "ounce": "oz", "ounces": "oz",
         "pound": "lb", "pounds": "lb", "kilogram": "kg", "kilograms": "kg"}.get(u, u)
    return u if u in UNIT_KG else None


def parse_number(text, dec_mark=".", thou_mark=","):
    t = text.strip().replace(" ", "").replace(" ", "")
    t = t.replace(thou_mark, "")
    if dec_mark != ".":
        t = t.replace(dec_mark, ".")
    return Decimal(t)


def weight_kg(text, unit, depot_fmt=(".", ",")):
    """text may carry its own unit suffix; unit is the fallback."""
    m = re.match(r"^\s*([-+0-9.,\s]+?)\s*([A-Za-z]+)?\s*$", text)
    if not m:
        return None
    own = norm_unit(m.group(2))
    try:
        v = parse_number(m.group(1), *depot_fmt)
    except InvalidOperation:
        return None
    u = own or unit or "kg"
    return v * UNIT_KG[u]


def month_of_date(s, form):
    s = s.strip()
    f = (form or "").strip()
    fu = f.upper()
    if fu == "SERIAL" or (re.fullmatch(r"\d{4,6}(\.\d+)?", s) and fu not in ("YYYYMMDD", "YYYYDDD")):
        d = date(1899, 12, 31) + timedelta(days=int(float(s)))
        if d >= date(1900, 3, 1):
            d -= timedelta(days=1)  # spreadsheet leap-year quirk; day 1 = 1899-12-31 per docs
        return d
    return None


def serial_date(s):
    # Documented: day 1 is 1899-12-31, so 46085 is 2026-03-04.
    return date(1899, 12, 31) + timedelta(days=int(float(s)))


def parse_date(s, form):
    """Return a UTC date from a ship date/time string."""
    s = s.strip()
    fu = (form or "").strip().upper()
    # full ISO 8601 time, with or without offset
    m = re.match(r"^(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:\.\d+)?)?\s*(Z|[+-]\d\d:?\d\d)?$", s)
    if m:
        y, mo, d, hh, mi, ss, off = m.groups()
        dt = datetime(int(y), int(mo), int(d), int(hh), int(mi), int(ss or 0))
        if off and off != "Z":
            sign = 1 if off[0] == "+" else -1
            digits = off[1:].replace(":", "")
            dt -= sign * timedelta(hours=int(digits[:2]), minutes=int(digits[2:]))
        return dt.date()
    if fu == "SERIAL":
        return serial_date(s)
    if fu in ("ISO", "YMD"):
        m = re.match(r"^(\d{4})-(\d\d)-(\d\d)", s)
        return date(*map(int, m.groups()))
    if fu == "DMY":
        m = re.match(r"^(\d\d)-(\d\d)-(\d{4})", s)
        return date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
    if fu in ("MM/DD/YYYY", "DD/MM/YYYY"):
        m = re.match(r"^(\d\d?)/(\d\d?)/(\d{4})", s)
        a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        return date(y, a, b) if fu == "MM/DD/YYYY" else date(y, b, a)
    if fu == "DD.MM.YYYY":
        m = re.match(r"^(\d\d?)\.(\d\d?)\.(\d{4})", s)
        return date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
    if fu == "YYYYMMDD":
        return date(int(s[0:4]), int(s[4:6]), int(s[6:8]))
    if fu == "YYYYDDD":
        return date(int(s[0:4]), 1, 1) + timedelta(days=int(s[4:7]) - 1)
    m = re.match(r"^(\d\d?) ([A-Za-z]{3})[a-z]* (\d{4})$", s)
    if m:
        return date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    raise ValueError("unparsable date %r (form %r)" % (s, form))


# ---------------------------------------------------------------- records
# A record is a dict: num, type, kg (Decimal|None), month ("YYYY-MM"|None), status
def make_record(num, typ, kg, when, status):
    return {"num": num, "type": typ, "kg": kg,
            "month": when.strftime("%Y-%m") if when else None, "status": status}


DIRECTIVE = re.compile(r"^#\s*([A-Za-z][A-Za-z ]*?)\s*:\s*(.*?)\s*$")


def logical_rows(text):
    """Yield ('comment', line) or ('row', raw_text) honouring quoted multi-line fields."""
    lines = text.replace("\r\n", "\n").split("\n")
    i = 0
    while i < len(lines):
        line = lines[i]
        i += 1
        if line.strip() == "":
            continue
        if line.startswith("#"):
            yield "comment", line
            continue
        buf = line
        while buf.count('"') % 2 == 1 and i < len(lines):
            buf += "\n" + lines[i]
            i += 1
        yield "row", buf


def parse_delimited(depot, text):
    delim = DELIM[depot]
    cols_known = set(COLUMNS[depot])
    dec_fmt = NUMFMT.get(depot, (".", ","))
    seq = None
    header = None
    dirs = {}
    out = []
    for kind, raw in logical_rows(text):
        if kind == "comment":
            m = re.search(r"\bseq\s*=\s*(\d+)", raw)
            if m and seq is None:
                seq = int(m.group(1))
            m = DIRECTIVE.match(raw)
            if m:
                name = m.group(1).lower().strip()
                dirs[name] = m.group(2)
                if name == "seq":
                    seq = int(re.search(r"\d+", m.group(2)).group(0))
            continue
        if depot == "east" or depot == "lakeside":
            fields = next(csv.reader([raw]))
        else:
            fields = raw.split(delim)
        low = [f.strip().lower() for f in fields]
        if low and all(f in cols_known for f in low):
            header = low
            continue
        if header is None:
            continue
        rec = build_delimited(depot, header, fields, dirs, dec_fmt)
        if rec:
            out.append(rec)
    return seq, out


def build_delimited(depot, header, fields, dirs, dec_fmt):
    own_unit = None
    n = len(header)
    if len(fields) == n + 1 and norm_unit(fields[-1]) and depot in ("east", "lakeside", "river", "west"):
        # row carries its own weight unit as an extra trailing field
        own_unit = norm_unit(fields[-1])
        fields = fields[:n]
    row = dict(zip(header, [f.strip() for f in fields]))
    if depot == "east":
        if row.get("id", "").upper() == "TOTAL" or not shipment_number(row.get("id")):
            return None
        typ = TYPE_MAP[row.get("type", "").lower()]
        unit = own_unit or norm_unit(dirs.get("unit")) or "kg"
        form = dirs.get("dates") or BASE_DATE[depot]
        return finish(depot, row["id"], typ, row.get("gross", ""), unit, dec_fmt,
                      row.get("shipped", ""), form, row.get("status", ""))
    if depot == "west":
        typ = TYPE_MAP[row.get("typ", "").lower()]
        unit = own_unit or norm_unit(dirs.get("weight unit")) or "kg"
        form = dirs.get("dates") or dirs.get("date format") or BASE_DATE[depot]
        return finish(depot, row["id"], typ, row.get("weight", ""), unit, dec_fmt,
                      row.get("shipped", ""), form, row.get("status", ""))
    if depot == "lakeside":
        typ = TYPE_MAP[row.get("kind", "").lower()]
        form = dirs.get("dates") or BASE_DATE[depot]
        return finish(depot, row["id"], typ, row.get("gross_kg", ""), own_unit or "kg", dec_fmt,
                      row.get("shipped", ""), form, row.get("status", ""))
    if depot == "river":
        typ = TYPE_MAP[row.get("t", "").lower()]
        unit = own_unit or norm_unit(dirs.get("weight unit")) or "kg"
        form = dirs.get("date format") or dirs.get("dates") or BASE_DATE[depot]
        return finish(depot, row["ref"], typ, row.get("weight", ""), unit, dec_fmt,
                      row.get("shipped", ""), form, row.get("status", ""))
    if depot == "harbor":
        typ = TYPE_MAP[row.get("rec", "").lower()]
        form = dirs.get("dates") or BASE_DATE[depot]
        status = {"dlv": "delivered", "dll": "delivered_late"}.get(
            row.get("state", "").lower(), row.get("state", ""))
        return finish(depot, row["ref"], typ, row.get("weight", ""), "kg", dec_fmt,
                      row.get("date", ""), form, status)
    return None


def finish(depot, rawid, typ, wtext, unit, dec_fmt, dtext, form, status):
    num = shipment_number(rawid)
    if num is None:
        return None
    if typ == "void":
        return make_record(num, typ, None, None, "")
    return make_record(num, typ, weight_kg(wtext, unit, dec_fmt),
                       parse_date(dtext, form) if dtext.strip() else None, norm_status(status))


def parse_json(text):
    seq = None
    out = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        obj = json.loads(line)
        items = obj if isinstance(obj, list) else [obj]
        for o in items:
            if not isinstance(o, dict):
                continue
            if "meta" in o and isinstance(o["meta"], dict) and "id" not in o:
                if "seq" in o["meta"]:
                    seq = int(o["meta"]["seq"])
                continue
            kind = TYPE_MAP.get(str(o.get("kind", "new")).lower(), "new")
            num = shipment_number(str(o.get("id", "")))
            if num is None:
                continue
            if kind == "void":
                out.append(make_record(num, kind, None, None, ""))
                continue
            kg = None
            for k, v in o.items():
                m = re.fullmatch(r"weight_([a-z]+)", k)
                if m and norm_unit(m.group(1)) and v is not None:
                    kg = Decimal(str(v)) * UNIT_KG[norm_unit(m.group(1))]
            when = parse_date(o["shipped_at"], "iso") if o.get("shipped_at") else None
            out.append(make_record(num, kind, kg, when, norm_status(o.get("status"))))
    return seq, out


def parse_xml(text):
    text = re.sub(r"^\s*<\?xml[^>]*\?>", "", text)
    root = ET.fromstring(text)
    seq = int(root.get("seq")) if root.get("seq") else None
    root_unit = norm_unit(root.get("weight-unit")) or "kg"
    out = []
    for el in root.iter("shipment"):
        num = shipment_number(el.get("id"))
        if num is None:
            continue
        typ = TYPE_MAP.get((el.get("type") or "new").lower(), "new")
        if typ == "void":
            out.append(make_record(num, typ, None, None, ""))
            continue
        w = el.find("weight")
        kg = None
        if w is not None and (w.text or "").strip():
            unit = norm_unit(w.get("unit")) or norm_unit(el.get("weight-unit")) or root_unit
            kg = weight_kg(w.text, unit)
        shipped = el.get("shipped")
        child = el.find("shipped")
        if child is not None and (child.text or "").strip():
            shipped = child.text
        when = parse_date(shipped, "iso") if shipped else None
        st = el.find("status")
        status = norm_status(st.text if st is not None else el.get("status"))
        out.append(make_record(num, typ, kg, when, status))
    return seq, out


LAYOUTS = {
    # name: (length, type, id, shipped, weight, status slices, date form, weight unit, scale)
    "FW1": dict(length=42, id=(0, 9), type=(9, 10), shipped=(10, 17), weight=(17, 25),
                status=(25, 26), form="YYYYDDD", unit="g", scale=Decimal(1)),
    "FW2": dict(length=43, type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26),
                status=(26, 27), form="YYYYMMDD", unit="kg", scale=Decimal("0.01")),
    "FW3": dict(length=41, id=(0, 9), shipped=(9, 16), type=(16, 17), weight=(17, 24),
                status=(24, 25), form="YYYYDDD", unit="lb", scale=Decimal("0.1")),
}
STATUS_CODES = {"D": "delivered", "L": "delivered_late", "C": "cancelled",
                "R": "returned", "H": "held"}


def parse_fixed(text):
    seq = None
    layout = None
    out = []
    for line in text.replace("\r\n", "\n").split("\n"):
        if line.strip() == "":
            continue
        if "\f" in line or line.lstrip().upper().startswith("SOUTH DEPOT"):
            continue
        if line.startswith("#"):
            m = re.match(r"#LAYOUT\s+(\w+)", line)
            if m:
                layout = m.group(1).upper()
            m = re.match(r"#SEQ\s+(\d+)", line)
            if m:
                seq = int(m.group(1))
            continue
        name = layout
        if name not in LAYOUTS or len(line) != LAYOUTS[name]["length"]:
            cands = [k for k, v in LAYOUTS.items() if v["length"] == len(line)]
            if len(cands) != 1:
                continue
            name = cands[0]
        L = LAYOUTS[name]
        g = lambda k: line[L[k][0]:L[k][1]]
        typ = TYPE_MAP.get(g("type").strip().lower(), "new")
        num = shipment_number(g("id"))
        if num is None:
            continue
        if typ == "void":
            out.append(make_record(num, typ, None, None, ""))
            continue
        kg = Decimal(int(g("weight"))) * L["scale"] * UNIT_KG[L["unit"]]
        when = parse_date(g("shipped"), L["form"])
        out.append(make_record(num, typ, kg, when, STATUS_CODES.get(g("status").strip().upper(), "")))
    return seq, out


def parse_file(depot, path):
    text = decode(read_bytes(path))
    text = text.lstrip("﻿")
    if depot == "central":
        return parse_xml(text)
    if depot == "north":
        return parse_json(text)
    if depot == "south":
        return parse_fixed(text)
    return parse_delimited(depot, text)


# ---------------------------------------------------------------- main
def main():
    data_dir, out_file = sys.argv[1], sys.argv[2]
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        path = os.path.join(data_dir, name)
        if not os.path.isfile(path):
            continue
        depot = name.split("-")[0].lower()
        exports.setdefault(depot, []).append((name, path))

    corrections = resends = 0
    current = {}  # depot -> {num: record}
    for depot, files in exports.items():
        parsed = []
        for name, path in files:
            seq, recs = parse_file(depot, path)
            parsed.append((seq if seq is not None else 0, name, recs))
        parsed.sort(key=lambda p: (p[0], p[1]))
        cur = current.setdefault(depot, {})
        for _, _, recs in parsed:
            for r in recs:
                n = r["num"]
                if r["type"] == "new":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["type"] == "correction":
                    cur[n] = r
                    corrections += 1
                elif r["type"] == "void":
                    cur.pop(n, None)
                    corrections += 1

    rank = {d: i for i, d in enumerate(DEPOT_ORDER)}
    holders = {}
    for depot, cur in current.items():
        for n in cur:
            holders.setdefault(n, []).append(depot)
    handovers = sum(1 for h in holders.values() if len(h) > 1)

    depots = {d: [0, Decimal(0)] for d in exports}
    months = {}
    for n, hs in holders.items():
        d = min(hs, key=lambda x: rank.get(x, 99))
        r = current[d][n]
        if not counted(r["status"]) or r["kg"] is None or r["month"] is None:
            continue
        depots[d][0] += 1
        depots[d][1] += r["kg"]
        m = months.setdefault(r["month"], [0, Decimal(0)])
        m[0] += 1
        m[1] += r["kg"]

    def fmt(v):
        return {"shipments": v[0], "total_kg": float(round(v[1], 2))}

    result = {
        "depots": {d: fmt(depots[d]) for d in sorted(depots)},
        "months": {k: fmt(months[k]) for k in sorted(months)},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as fh:
        json.dump(result, fh, indent=2)
        fh.write("\n")


if __name__ == "__main__":
    main()

